package cn.musicsquare.app;
import org.json.*;
public class LiveDiscoveryProbe{
 public static void main(String[] args)throws Exception{
  CatalogApi api=new CatalogApi();JSONObject a=api.request(new JSONObject().put("operation","search").put("kind","artist").put("keyword","林俊杰").put("offset",0));if(a.getJSONArray("items").length()==0)throw new AssertionError("no artists");JSONObject artist=a.getJSONArray("items").getJSONObject(0);System.out.println("PASS artist search: "+artist.getString("name")+" id="+artist.getString("id"));
  JSONObject detail=api.request(new JSONObject().put("operation","artist").put("id",artist.getString("id")));if(detail.getJSONArray("tracks").length()==0)throw new AssertionError("no songs");System.out.println("PASS artist hot tracks: "+detail.getJSONArray("tracks").length());
  JSONObject pl=api.request(new JSONObject().put("operation","search").put("kind","playlist").put("keyword","林俊杰").put("offset",0));if(pl.getJSONArray("items").length()==0)throw new AssertionError("no playlists");System.out.println("PASS playlist search: "+pl.getJSONArray("items").length());
  JSONObject first=api.request(new JSONObject().put("operation","playlist").put("id","3778678").put("offset",0)),second=api.request(new JSONObject().put("operation","playlist").put("id","3778678").put("offset",20));if(first.getJSONArray("tracks").length()==0||second.getJSONArray("tracks").length()==0)throw new AssertionError("missing playlist page");if(first.getJSONArray("tracks").getJSONObject(0).getString("uid").equals(second.getJSONArray("tracks").getJSONObject(0).getString("uid")))throw new AssertionError("repeated page");System.out.println("PASS playlist detail and ID-based second-page hydration: "+first.getJSONArray("tracks").length()+" + "+second.getJSONArray("tracks").length());
  JSONObject rec=api.request(new JSONObject().put("operation","recommend"));System.out.println("PASS recommended playlists: "+rec.getJSONArray("items").length());
  PlaybackCache.Store memory=new PlaybackCache.Store(){String data="{}";public String read(){return data;}public void write(String value){data=value;}};PlaybackCache cache=new PlaybackCache(memory);JSONObject song=MusicApi.base("netease","108485","Always Online","林俊杰").put("durationMs",225013);long t=System.nanoTime();JSONObject resolved=cache.resolve(song,false);long miss=(System.nanoTime()-t)/1000000;t=System.nanoTime();JSONObject hit=cache.resolve(song,false);long warm=(System.nanoTime()-t)/1000000;if(!hit.optBoolean("audioFromCache"))throw new AssertionError("cache miss");System.out.println("PASS live URL cache: first resolve="+miss+"ms; cached resolve="+warm+"ms; provider="+resolved.optString("playbackProvider")+"; no audio URL logged");
  System.out.println("Scope: production Java catalog and cached resolver in server network. Not Android device timings or full end-to-end playback.");
 }
}
